// Supondo que o item do n8n tenha o markdown no campo "text"
const markdownItem = $json["content"].parts[0].text;

// Remove os backticks e "json"
const cleaned = markdownItem
    .replace(/```json\s*/, '')  // remove ```json no início
    .replace(/```/, '')         // remove ``` no final
    .trim();

// Converte para JSON
const parsed = JSON.parse(cleaned);

// Retorna como saída do Function Node
return [
  {
    json: parsed
  }
];

// Função para gerar UUID v4
function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

// Adiciona o UUID ao item
return [
  {
    json: {
      ...$json,
      documentId: uuidv4() // novo campo com UUID
    }
  }
];

