// Pega o item do Webhook
const webhookItem = $items('Webhook')[0]; // primeiro item do nó Webhook
const body = webhookItem.json.body || {};

// Número do WhatsApp original (sem normalizar)
const numeroWhatsAppOriginal = body.payload?.from || "";

// Número do WhatsApp normalizado
let numeroWhatsApp = "";
if (numeroWhatsAppOriginal.endsWith("@c.us")) {
  const raw = numeroWhatsAppOriginal.replace("@c.us", "");
  numeroWhatsApp = raw.startsWith("55") ? raw.substring(2) : raw;
}

// Função para normalizar telefone do banco
function normalizarTelefone(telefone) {
  if (!telefone) return "";
  return telefone
    .replace(/\D/g, "")        // remove tudo que não é número
    .replace(/^55/, "");       // remove o 55 do começo se existir
}

// Pega os outros campos do webhook de forma segura
const url = body.payload?.media?.[0]?.url || "";
const messageType = body.payload?._data?.Info?.Type || "";
const mediaType = body.payload?._data?.Info?.MediaType || "";
const senderTimestamp = body.payload?._data?.Message?.messageContextInfo?.deviceListMetadata?.senderTimestamp || "";

// Percorre todos os usuários do Firestore
const usuarios = $items("Usuario Fire"); // node que trouxe os usuários
let encontrados = [];

for (const usuario of usuarios) {
  const telefoneBanco = usuario.json.fields?.telefone?.stringValue || "";
  const telNormalizado = normalizarTelefone(telefoneBanco);

  if (telNormalizado && telNormalizado === numeroWhatsApp) {
    encontrados.push({
      id: usuario.json.id,
      nome: usuario.json.fields?.name?.stringValue || "",
      email: usuario.json.fields?.email?.stringValue || "",
      telefoneFirebase: telefoneBanco,         // telefone original do Firebase
      telefoneNormalizado: telNormalizado,    // versão limpa do Firebase
      numeroWhatsApp,                          // número normalizado
      numeroWhatsAppOriginal,                  // número original do WhatsApp
      match: true,
      // novos campos
      url,
      messageType,
      mediaType,
      senderTimestamp
    });
  }
}

// Retorna o resultado
return encontrados.length > 0
  ? encontrados.map(u => ({ json: u }))
  : [{
      json: {
        match: false,
        numeroWhatsApp,
        numeroWhatsAppOriginal,
        telefoneFirebase: null,
        url,
        messageType,
        mediaType,
        senderTimestamp
      }
    }];
